-- 311: Seed 6 corporate case-study blog posts (MMD_Blog). Adapted from the
-- Tertiary Infotech reference posts but rewritten to funnel to the matching
-- www.tertiarycourses.com.sg WSQ course page (related_skus) with the WSQ funding
-- + SkillsFuture / SFEC hooks. Reference publish dates preserved.
--
-- Idempotent (WHERE NOT EXISTS on url_key); content is ONE line per INSERT
-- (apply.php splitter); single quotes SQL-doubled (''). source_sku left NULL
-- (these are case studies, not the canonical per-course blog) so they don't
-- affect the autoblog course picker; related_skus drives the sign-up CTA.

-- 1) Qualcomm — Agentic AI with n8n (2026-06-04) -> n8n course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Corporate Agentic AI with n8n Training for Qualcomm', 'corporate-agentic-ai-n8n-training-qualcomm', 'How 15 Qualcomm operations staff shipped 6 production AI workflows in a 3-day hands-on n8n cohort — and how your team can do the same with up to 70% WSQ funding.', '<h2>The brief: turn 15 ops staff into automation builders in 3 days</h2><p>Qualcomm sent 15 operations staff to a three-day, hands-on cohort with one goal: leave able to build real AI workflows, not just talk about them. The guiding rule throughout was simple — <strong>every concept is shipped before the next concept is taught</strong>.</p><h2>What we covered</h2><ul><li>n8n fundamentals — nodes, triggers and data mapping across apps</li><li>AI agents with tool-calling that act, not just chat</li><li>Webhook integration to connect external systems</li><li>Retrieval-augmented generation (RAG) for document Q&amp;A</li><li>Multi-agent orchestration (supervisor + specialist patterns)</li></ul><h2>What the team shipped</h2><p>By the end, participants had deployed six production-ready artefacts: a QR-driven event registration form, an AI agent with tool integration, a webhook-triggered static site, a document Q&amp;A chatbot, a supervisor-specialist multi-agent system, and an image-classification pipeline. Everyone left with working workflows and the GitHub materials to keep building.</p><p>The same curriculum is our public <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">WSQ Agentic AI Automation with n8n course</a>.</p><h2>Bring this to your team</h2><p>Run it as a public WSQ class or as on-site corporate training tailored to your systems. As a <strong>WSQ-accredited course it attracts up to 70% funding</strong> for eligible Singaporeans and PRs, staff can use <strong>SkillsFuture Credit</strong>, and companies can stack <strong>SkillsFuture Enterprise Credit (SFEC)</strong> plus absentee payroll support. <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">View class dates and register here</a>.</p><h2>FAQ</h2><h3>Do participants need coding experience?</h3><p>No. n8n is visual and low-code; the cohort starts from fundamentals and builds up to multi-agent systems.</p><h3>Can you run this on our own tools and data?</h3><p>Yes — corporate runs are tailored to your stack and use cases. Ask us about an on-site cohort.</p><h3>Is it funded?</h3><p>Yes — WSQ funding up to 70%, SkillsFuture Credit and SFEC all apply.</p><h2>What to do next</h2><ol><li>Pick one repetitive workflow your team would love to automate</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}"><strong>WSQ Agentic AI Automation with n8n</strong></a> class, or ask about an on-site cohort</li><li>Leave with deployed AI workflows, not slides</li></ol>', 'Tertiary Infotech Academy', 1, '2026-06-04', 'TGS-2023035977', 'Corporate n8n Agentic AI Training (Qualcomm) | WSQ Funded', 'How Qualcomm ops staff shipped 6 AI workflows in a 3-day n8n cohort. Run it for your team with up to 70% WSQ funding + SkillsFuture.', 'n8n corporate training, agentic ai, qualcomm, workflow automation, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'corporate-agentic-ai-n8n-training-qualcomm');

-- 2) Red Beacon Asset Management — Claude Code (2026-05-28) -> Claude Code course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Corporate Claude Code Training at Red Beacon Asset Management', 'corporate-claude-code-training-red-beacon-asset-management', 'A one-day Claude Code workshop turned 10 non-developer finance staff into builders who shipped a live website. Here is what they learned — and how to run it for your team with WSQ funding.', '<h2>The brief: agentic coding for a non-developer team</h2><p>Red Beacon Asset Management, a Singapore-based wealth manager, sent 10 staff — a mix of investment and operations professionals, not developers — to a one-day Claude Code workshop. The goal: build a functioning asset-management landing page with lead capture, and learn the agentic mechanics behind it.</p><h2>The four agentic mechanics they mastered</h2><ul><li><strong>Custom commands</strong> — reusable prompts stored as Markdown (e.g. <em>/new-section</em>) for consistent workflows</li><li><strong>MCP tools</strong> — connecting the agent to external systems (browser testing, databases) so it executes, not just suggests</li><li><strong>Skills</strong> — domain-knowledge packages encoding brand voice and compliance rules</li><li><strong>Hooks &amp; sub-agents</strong> — automated lifecycle behaviours and specialist agents for tasks like compliance review</li></ul><h2>The result</h2><p>Every participant deployed a working website to a public URL and walked away with a personal toolkit of commands and skills they can reuse. The big lesson: <strong>agentic mechanics translate cleanly to non-developer teams</strong>. The same curriculum is our public <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}">WSQ Agentic AI Applications with Claude Code course</a>.</p><h2>Bring this to your team</h2><p>Book the public WSQ class or an on-site corporate cohort. It is a <strong>WSQ-accredited course</strong>, so eligible Singaporeans and PRs get <strong>up to 70% funding</strong>, staff can apply <strong>SkillsFuture Credit</strong>, and companies stack <strong>SFEC</strong> plus absentee payroll. <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}">See dates and register</a>.</p><h2>FAQ</h2><h3>Is this suitable for non-developers?</h3><p>Yes — the Red Beacon cohort were finance and ops professionals. You describe intent in English; the agent writes and runs the code.</p><h3>Can it be tailored to our brand and compliance rules?</h3><p>Yes — Skills encode your brand voice and compliance requirements. On-site runs use your context.</p><h3>Can we use SkillsFuture Credit?</h3><p>Yes, plus WSQ funding and SFEC for company-sponsored staff.</p><h2>What to do next</h2><ol><li>Identify one tool or page your team keeps needing</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-agentic-ai-applications-with-claude-code.html''}}"><strong>WSQ Agentic AI Applications with Claude Code</strong></a> class, or ask about an on-site cohort</li><li>Leave with a deployed app and a reusable agentic toolkit</li></ol>', 'Tertiary Infotech Academy', 1, '2026-05-28', 'TGS-2025052468', 'Corporate Claude Code Training (Red Beacon) | WSQ Funded', 'A one-day Claude Code workshop turned 10 finance staff into builders who shipped a live site. Run it for your team — up to 70% WSQ funding.', 'claude code corporate training, agentic ai, mcp, red beacon, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'corporate-claude-code-training-red-beacon-asset-management');

-- 3) MINDEF — OpenClaw harness engineering (2026-05-13) -> OpenClaw course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'OpenClaw Harness Engineering for MINDEF', 'openclaw-harness-engineering-mindef', 'From prompt engineering to harness engineering: how 19 MINDEF professionals learned to configure and govern AI agents with OpenClaw — and how your team can build the same skills with WSQ funding.', '<h2>Beyond prompts: the shift to harness engineering</h2><p>Nineteen Ministry of Defence professionals joined a specialised session on <strong>OpenClaw</strong>, tracing AI''s professional evolution across three phases: prompt engineering (2023), context engineering (2024), and today''s <strong>harness engineering</strong> — orchestrating AI agents inside reliable, governed frameworks rather than crafting one-off prompts.</p><h2>What the session covered</h2><ul><li>Why a structured <em>harness</em> beats ad-hoc prompting for consistency and control</li><li>Configuring a personal OpenClaw instance with pre-built logic and integrations</li><li>Model selection and setting up communication channels for real workflows</li><li>Governing AI tools — the standardisable skills organisations now need</li></ul><h2>The takeaway</h2><p>Rather than asking every user to write prompts from scratch, OpenClaw provides a structured harness with reusable logic and integrations. The organisations that win are the ones whose staff can <strong>configure and govern</strong> AI tools — teachable, standardisable skills. Explore the same ideas in our <a href="{{store direct_url=''wsq-business-innovation-with-openclaw-and-blockchain.html''}}">WSQ Business Innovation with OpenClaw and Blockchain course</a>.</p><h2>Bring this to your team</h2><p>Available as a public WSQ class or an on-site corporate cohort. As a <strong>WSQ-accredited course</strong> it attracts <strong>up to 70% funding</strong>, staff can use <strong>SkillsFuture Credit</strong>, and companies add <strong>SFEC</strong> plus absentee payroll support. <a href="{{store direct_url=''wsq-business-innovation-with-openclaw-and-blockchain.html''}}">View dates and register</a>.</p><h2>FAQ</h2><h3>Do we need a technical team for this?</h3><p>No — harness engineering is about configuring and governing AI tools, which is teachable to business and operations staff.</p><h3>Can it be run for a whole department?</h3><p>Yes — on-site corporate cohorts are tailored to your workflows and governance needs.</p><h3>Is funding available?</h3><p>Yes — WSQ funding, SkillsFuture Credit and SFEC all apply.</p><h2>What to do next</h2><ol><li>Map one workflow where your team currently re-writes prompts by hand</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-business-innovation-with-openclaw-and-blockchain.html''}}"><strong>WSQ Business Innovation with OpenClaw and Blockchain</strong></a> class, or ask about an on-site cohort</li><li>Leave able to configure and govern AI agents with a reliable harness</li></ol>', 'Tertiary Infotech Academy', 1, '2026-05-13', 'TGS-2020503395', 'OpenClaw Harness Engineering Training (MINDEF) | WSQ Funded', 'How 19 MINDEF staff learned to configure and govern AI agents with OpenClaw. Build the same skills with up to 70% WSQ funding.', 'openclaw, harness engineering, ai governance, mindef, corporate training, wsq funding', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'openclaw-harness-engineering-mindef');

-- 4) Kajima — AI governance (2026-04-27) -> AI Ethics & Responsible AI course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Why Kajima Chose AI Governance Training in 2026', 'kajima-responsible-generative-ai-governance-training-2026', 'PDPA exposure, confidential data leaking into public AI, copyright risk — why Kajima trained its Singapore staff in responsible AI governance, and how you can too with up to 90% funding.', '<h2>The driver: adopt AI without the legal exposure</h2><p>Kajima, a major Japanese construction and engineering firm with Singapore operations, wanted to embrace generative AI without the risk. The gaps were clear: <strong>PDPA compliance</strong>, confidential data being ingested by public AI models, copyright exposure from AI-generated content, and the absence of a clear internal governance framework.</p><h2>What the one-day WSQ programme covered</h2><ul><li><strong>Ethical principles</strong> for evaluating AI outputs</li><li><strong>Privacy techniques</strong> — data anonymisation aligned with PDPA</li><li><strong>Responsible development</strong> — intellectual property and governance frameworks</li></ul><h2>The outcome</h2><p>Participants left understanding the legal boundaries and how to structure internal AI usage policies — <strong>a foundation for responsible adoption rather than a blanket ban</strong>. The same curriculum is our public <a href="{{store direct_url=''wsq-fundamentals-of-ai-ethics-and-responsible-ai.html''}}">WSQ Fundamentals of AI Ethics and Responsible AI course</a>.</p><h2>The funding maths</h2><p>Because it is <strong>WSQ-accredited</strong>, eligible Singaporeans and PRs get <strong>up to 70% funding</strong> (up to 90% for SMEs and MCES-eligible learners), staff can apply <strong>SkillsFuture Credit</strong>, and companies can stack <strong>SkillsFuture Enterprise Credit (SFEC)</strong> — bringing the per-participant cost down dramatically. <a href="{{store direct_url=''wsq-fundamentals-of-ai-ethics-and-responsible-ai.html''}}">Check eligibility and dates</a>.</p><h2>FAQ</h2><h3>Is this only for legal or compliance teams?</h3><p>No — it is designed for any staff using AI, so the whole organisation shares one governance baseline.</p><h3>Does it cover PDPA specifically?</h3><p>Yes — data anonymisation and privacy techniques are aligned to PDPA requirements.</p><h3>How much can we save with funding?</h3><p>WSQ funding plus SFEC can reduce the per-participant cost to a fraction of the list fee.</p><h2>What to do next</h2><ol><li>List the AI risks your organisation is currently exposed to (data, copyright, policy)</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-fundamentals-of-ai-ethics-and-responsible-ai.html''}}"><strong>WSQ Fundamentals of AI Ethics and Responsible AI</strong></a> class, or ask about an on-site cohort</li><li>Leave with a governance foundation for responsible AI adoption</li></ol>', 'Tertiary Infotech Academy', 1, '2026-04-27', 'TGS-2023021102', 'AI Governance Training (Kajima Case Study) | WSQ Funded', 'Why Kajima trained staff in responsible AI governance — PDPA, data leakage, copyright. Run it for your team with up to 90% funding.', 'ai governance, responsible ai, pdpa, ai ethics, corporate training, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'kajima-responsible-generative-ai-governance-training-2026');

-- 5) Charles & Keith — GenAI problem solving (2026-03-30) -> Problem Solving w/ GenAI course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Charles & Keith: A GenAI Problem-Solving Workshop with 20 Cross-Functional Staff', 'charles-and-keith-genai-problem-solving-training-singapore', 'Twenty Charles & Keith staff from Ops, Marketing, Finance and HR solved four real business problems with generative AI in two days. Here is how — and how to run it for your team with WSQ funding.', '<h2>Real problems beat hypothetical ones</h2><p>Around 20 employees from Charles &amp; Keith''s Operations, Marketing, Finance and HR functions joined a two-day generative-AI workshop. Instead of generic AI instruction, cross-functional teams tackled four business-specific challenges — because <strong>real problems build more durable solutions</strong>.</p><h2>The four challenges the teams prototyped</h2><ul><li><strong>Stock imbalance</strong> — an AI assistant flagging inventory mismatches across stores</li><li><strong>Marketing approvals</strong> — a GenAI brief assistant to speed up multi-stage approvals</li><li><strong>Talent retention</strong> — a manager-support tool synthesising feedback patterns (deliberately avoiding predictive-termination modelling)</li><li><strong>Finance reporting</strong> — a workflow drafting variance commentary and surfacing anomalies</li></ul><h2>The lesson that mattered most</h2><p>Beyond building, participants learned what GenAI should <em>not</em> do — refusing an inappropriate predictive model in favour of an ethical alternative. Cross-functional teams consistently produced the most durable solutions. The same approach powers our public <a href="{{store direct_url=''wsq-identifying-and-solving-problems-at-the-workplace.html''}}">WSQ Innovative Problem Solving with Generative AI course</a>.</p><h2>Bring this to your team</h2><p>Run it as a public WSQ class or an on-site corporate cohort built around your real problems. As a <strong>WSQ-accredited course</strong> it attracts <strong>up to 70% funding</strong>, staff can use <strong>SkillsFuture Credit</strong>, and companies stack <strong>SFEC</strong> plus absentee payroll. <a href="{{store direct_url=''wsq-identifying-and-solving-problems-at-the-workplace.html''}}">View dates and register</a>.</p><h2>FAQ</h2><h3>Should we send one team or a mix?</h3><p>A cross-functional mix works best — Charles &amp; Keith spanned Ops, Marketing, Finance and HR, and the diversity produced stronger solutions.</p><h3>Can we bring our own problems?</h3><p>Yes — on-site cohorts are built around your live business challenges.</p><h3>Is it funded?</h3><p>Yes — WSQ funding, SkillsFuture Credit and SFEC all apply.</p><h2>What to do next</h2><ol><li>Shortlist three real problems across different functions</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-identifying-and-solving-problems-at-the-workplace.html''}}"><strong>WSQ Innovative Problem Solving with Generative AI</strong></a> class, or ask about an on-site cohort</li><li>Leave with working prototypes for your own business problems</li></ol>', 'Tertiary Infotech Academy', 1, '2026-03-30', 'TGS-2023036653', 'GenAI Problem-Solving Workshop (Charles & Keith) | WSQ Funded', 'How 20 Charles & Keith staff solved 4 real business problems with GenAI in 2 days. Run it for your team with up to 70% WSQ funding.', 'generative ai, problem solving, charles and keith, corporate training, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'charles-and-keith-genai-problem-solving-training-singapore');

-- 6) MSIG — custom n8n (2025-11-11) -> n8n course
INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `meta_title`, `meta_description`, `meta_keywords`, `created_at`, `updated_at`) SELECT 'Custom n8n Training for MSIG Staff: Security & Finance Automation', 'custom-n8n-training-for-msig-staff', 'MSIG trained its staff to automate insurance finance workflows on self-hosted n8n — securely. Here is what they built, and how your team can learn the same with up to 70% WSQ funding.', '<h2>The brief: automate insurance workflows without leaking data</h2><p>MSIG ran an on-site n8n programme focused on two things insurers care about most: <strong>securing sensitive data</strong> through self-hosted infrastructure, and <strong>automating financial workflows</strong> like reconciliation and reporting. Rather than generic demos, the team worked with MSIG''s own systems and context.</p><h2>What the team learned</h2><ul><li>Credential management and webhook security for sensitive data</li><li>Audit-trail implementation for compliance</li><li>Approval-routing workflows for finance operations</li><li>Reconciliation and reporting automation</li></ul><h2>Why n8n for regulated automation</h2><p>With 400+ native integrations, robust error handling and self-hosting, n8n outperforms lighter tools like Flowise and Langflow when <strong>data residency and system integration</strong> matter more than prototype speed — exactly the case for production insurance automation. The same curriculum is our public <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">WSQ Agentic AI Automation with n8n course</a>.</p><h2>Bring this to your team</h2><p>Run it as a public WSQ class or an on-site corporate cohort on your own infrastructure. As a <strong>WSQ-accredited course</strong> it attracts <strong>up to 70% funding</strong>, staff can use <strong>SkillsFuture Credit</strong>, and companies stack <strong>SFEC</strong> plus absentee payroll. <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}">View dates and register</a>.</p><h2>FAQ</h2><h3>Can the training use our own self-hosted setup?</h3><p>Yes — on-site cohorts work with your infrastructure, credentials policy and audit requirements.</p><h3>Is n8n secure enough for regulated data?</h3><p>Self-hosting keeps data in your environment; the course covers credential management, webhook security and audit trails.</p><h3>Is it funded?</h3><p>Yes — WSQ funding, SkillsFuture Credit and SFEC all apply.</p><h2>What to do next</h2><ol><li>Pick one finance or ops workflow that must stay in-house</li><li>Reserve seats in the <a href="{{store direct_url=''wsq-agentic-ai-automation-with-n8n.html''}}"><strong>WSQ Agentic AI Automation with n8n</strong></a> class, or ask about an on-site cohort</li><li>Leave able to automate securely on self-hosted n8n</li></ol>', 'Tertiary Infotech Academy', 1, '2025-11-11', 'TGS-2023035977', 'Custom n8n Training for MSIG | Secure Finance Automation', 'How MSIG staff learned to automate insurance finance workflows securely on self-hosted n8n. Learn the same with up to 70% WSQ funding.', 'n8n, insurance automation, msig, self-hosted, corporate training, wsq funding, skillsfuture', NOW(), NOW() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `mmd_blog_post` WHERE `url_key` = 'custom-n8n-training-for-msig-staff');

